const ctx = $input.first().json || {};

const link = ctx.short_url || ctx.checkout_url || '';

const country = String(ctx.country || '').toLowerCase();
const currency = String(ctx.currency || '').toUpperCase();
const amount = String(ctx.amount || '');

let amountLabel = `${currency} ${amount}`.trim();

if (country === 'india' && currency === 'INR') {
  amountLabel = `Rs${amount}`;
}

if (country === 'nepal' && currency === 'NPR') {
  amountLabel = `Rs${amount}`;
}

let brand = 'Landmark Markets';

const text = `${brand}: ${amountLabel} payment link: ${link}`;

return [{
  json: {
    ...ctx,
    sms_text: text
  }
}];

const smsResponse = $input.first().json;

let ctx = null;

try {
  ctx = $('🇮🇳 Parse OkPay Response').first().json;
} catch (e) {}

if (!ctx) {
  try {
    ctx = $('🇳🇵 Parse Monetix Response [CONFIG REQUIRED]').first().json;
  } catch (e) {}
}

ctx = ctx || {};

return [{
  json: {
    ...ctx,
    sms_response: smsResponse
  }
}];

const b = $input.first().json.body || $input.first().json;

function canonicalCountry(rawCountry, rawPhone='') {
  const c = String(rawCountry || '').trim().toLowerCase();

  if (['india','in'].includes(c)) return 'india';
  if (['nepal','np'].includes(c)) return 'nepal';

  const p = String(rawPhone || '').replace(/[^0-9+]/g,'');

  if (p.startsWith('+977') || p.startsWith('977')) return 'nepal';
  if (p.startsWith('+91') || p.startsWith('91')) return 'india';

  return '';
}

function normalizeDigits(rawPhone, country) {
  let d = String(rawPhone || '')
    .replace(/^=+/, '')
    .replace(/[^0-9]/g, '');

  if (!d) return '';

  if (country === 'india') {
    if (d.startsWith('91') && d.length === 12) return d;
    if (d.length === 10) return '91' + d;
  }

  if (country === 'nepal') {
    if (d.startsWith('977') && d.length >= 11 && d.length <= 15) return d;
    if (d.length >= 8 && d.length <= 10) return '977' + d;
  }

  return d;
}

const rawPhone = b.phone || b.lead_id || '';
const country = canonicalCountry(b.country, rawPhone);
const clientPhone = normalizeDigits(rawPhone, country);

let whatsapp_phone = String(b.whatsapp_phone || '')
  .replace(/^=+/, '')
  .replace(/[^0-9]/g, '');

if (whatsapp_phone) {
  whatsapp_phone = normalizeDigits(whatsapp_phone, country);
} else {
  whatsapp_phone = clientPhone;
}

if (whatsapp_phone) whatsapp_phone = '+' + whatsapp_phone;

// Multi-country default currency.
// India -> INR
// Nepal -> NPR
const defaultCurrency =
  country === 'india' ? 'INR' :
  country === 'nepal' ? 'NPR' :
  '';

return [{
  json: {
    lead_id: String(b.lead_id || Date.now()).replace(/^=+/, '').trim(),
    full_name: String(b.full_name || 'friend').replace(/^=+/, '').trim(),
    phone: clientPhone,
    whatsapp_phone,
    country,
    _source_sheet: ({
      india: 'leads',
      nepal: 'leads nepal',
      slot3: 'leads slot3',
      slot4: 'leads slot4'
    })[country] || '',
    currency: String(b.currency || defaultCurrency).toUpperCase(),
    amount: b.amount || 2000,
    risk_disclosure_confirmed: true
  }
}];

// MULTI-COUNTRY PAYMENT GUARD + ORDER BUILDER
// India -> OkPay
// Nepal -> Monetix
//
// IMPORTANT:
// Nepal gateway credentials, endpoint, signing method and final minimum amount
// are intentionally NOT invented here. The Monetix branch is created separately
// and remains safe until its technical configuration is completed.

const j = $input.first().json || {};

const lead_id   = String(j.lead_id || '').trim();
const full_name = String(j.full_name || '').trim();
const phone     = String(j.phone || '').replace(/[^0-9]/g, '');
const country   = String(j.country || '').trim().toLowerCase();
const currency  = String(j.currency || '').trim().toUpperCase();
const amountNum = Number(String(j.amount || '0').replace(/^=/, '').trim());

const riskConfirmed =
  j.risk_disclosure_confirmed === true ||
  j.risk_disclosure_confirmed === 'true';

let whatsapp_phone = String(j.whatsapp_phone || '').replace(/[^0-9+]/g, '');
if (!whatsapp_phone) whatsapp_phone = phone ? ('+' + phone) : '';
if (whatsapp_phone && !whatsapp_phone.startsWith('+')) {
  whatsapp_phone = '+' + whatsapp_phone;
}

const payment_provider =
  country === 'india' ? 'okpay' :
  country === 'nepal' ? 'monetix' :
  '';

const errs = [];

if (!lead_id) errs.push('missing lead_id');
if (!phone) errs.push('missing phone');
if (!country) errs.push('unsupported/missing country');

if (!['india', 'nepal'].includes(country)) {
  errs.push('unsupported country: ' + country);
}

if (!payment_provider) {
  errs.push('payment provider not configured');
}

if (country === 'india' && currency !== 'INR') {
  errs.push('India payment currency must be INR');
}

if (country === 'nepal' && currency !== 'NPR') {
  errs.push('Nepal payment currency must be NPR');
}

// Preserve the existing India minimum exactly.
// Nepal minimum is still pending Monetix confirmation, therefore only require > 0 here.
// The Monetix request branch remains blocked until its API details are configured.
if (country === 'india' && (!Number.isFinite(amountNum) || amountNum < 2000)) {
  errs.push('India amount must be >= 2000');
}

if (country === 'nepal' && (!Number.isFinite(amountNum) || amountNum <= 0)) {
  errs.push('Nepal amount must be greater than 0');
}

if (Number.isFinite(amountNum) && amountNum > 500000) {
  errs.push('amount exceeds sanity ceiling 500000');
}

if (!riskConfirmed) {
  errs.push('risk_disclosure_confirmed must be true');
}

if (errs.length) {
  return [{
    json: {
      success: false,
      refused: true,
      country,
      payment_provider,
      reason: errs.join('; '),
      user_message: 'Payment link unavailable: ' + errs.join(', ')
    }
  }];
}

const out_trade_no = 'LM_' + lead_id + '_' + Date.now();
const idempotency_key = 'pay_' + out_trade_no;

return [{
  json: {
    ok: true,
    lead_id,
    full_name,
    phone,
    whatsapp_phone,
    country,
    currency,
    payment_provider,
    amount: String(Math.floor(amountNum)),
    out_trade_no,
    idempotency_key
  }
}];

