function clean(v) {
  return String(v || '').replace(/=/g, '').trim();
}

const ctx = $input.first().json;

// E.164 already normalized upstream; do not force +91 in a multi-country workflow.
let whatsapp_phone = String(ctx.whatsapp_phone || ctx.phone || '').replace(/[^0-9+]/g, '');
if (whatsapp_phone && !whatsapp_phone.startsWith('+')) whatsapp_phone = '+' + whatsapp_phone;

const params = {
  mchId:        '2764',
  currency:     clean(ctx.currency),
  out_trade_no: clean(ctx.out_trade_no),
  pay_type:     'UPI',
  money:        clean(ctx.amount),
  notify_url:   'https://landmarket-n8n.dhsoig.easypanel.host/webhook/okpay-callback',
  returnUrl:    'https://www.landmarkmarkets.in/sign-in',
  phone:        clean(ctx.phone),
  attach:       clean(ctx.lead_id),
};

const filtered = {};
for (const k of Object.keys(params)) {
  const v = params[k];
  if (v !== '' && v !== null && v !== undefined) filtered[k] = v;
}

const sortedKeys = Object.keys(filtered).sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
const baseString = sortedKeys.map(k => k + '=' + filtered[k]).join('&');
const toSign = baseString + '&key=' + 'a421742f0b404661b8ddb323c51cc99b';
const sign = md5(toSign);

const bodyParts = sortedKeys.map(k => encodeURIComponent(k) + '=' + encodeURIComponent(filtered[k]));
bodyParts.push('sign=' + sign);
const formBody = bodyParts.join('&');

return [{ json: { ...ctx, ...filtered, whatsapp_phone, sign, formBody } }];

const resp = $input.first().json || {};
const ctx = $('🇮🇳 Build OkPay Signed Request').first().json;

const code = resp.statusCode ?? resp.status ?? null;
const body = resp.body || resp;

const okpayCode = body.code;
const url = body.data && body.data.url;
const txnId = body.data && (body.data.transaction_Id || body.data.transactionId);

const success =
  code &&
  code >= 200 &&
  code < 300 &&
  okpayCode === 0 &&
  url;

if (success) {
  return [{
    json: {
      ...ctx,
      success: true,
      payment_provider: 'okpay',
      checkout_url: url,
      payment_transaction_id: txnId,
      okpay_transaction_id: txnId,
      http_status: code
    }
  }];
}

return [{
  json: {
    ...ctx,
    success: false,
    refused: false,
    payment_provider: 'okpay',
    reason:
      'OkPay error code=' + okpayCode +
      ' msg=' + (body.msg || '') +
      ' http=' + code,
    user_message:
      'Payment link generate karne mein technical issue aaya. Thodi der baad try karte hain.'
  }
}];

// Return a clean, tool-friendly response to the AI Agent.
const j = $input.first().json || {};

if (j.success) {
  const isNepal = String(j.country || '').toLowerCase() === 'nepal';

  return [{
    json: {
      success: true,
      country: j.country,
      payment_provider: j.payment_provider,
      message_to_user: isNepal
        ? 'Your payment link has been sent by SMS. Please check it and confirm. Trading involves risk.'
        : 'Payment link aapko SMS pe bhej diya hai. Check kar ke confirm karein. Yaad rahe — trading mein risk hota hai.',
      out_trade_no: j.out_trade_no,
      amount: j.amount,
      currency: j.currency
    }
  }];
}

return [{
  json: {
    success: false,
    country: j.country,
    payment_provider: j.payment_provider,
    message_to_user:
      j.user_message ||
      'Payment link generate karne mein issue aaya. Thodi der baad try karte hain.',
    reason: j.reason
  }
}];

const j = $input.first().json;
return [{ json: {
  success: false,
  refused: true,
  message_to_user: j.user_message || ('Payment link refused: ' + j.reason),
  reason: j.reason
}}];

// NEPAL / MONETIX REQUEST BUILDER — STRUCTURE READY
// This node is intentionally safe until the Monetix technical team provides:
// - API endpoint
// - merchant/account identifier
// - authentication/signature method
// - secret/API key
// - exact request field names
// - callback/notify URL requirements
// - success response format
// - minimum/maximum amount rules
//
// Once those details arrive, replace ONLY the configuration/payload section
// in this node and then configure/enable the HTTP node that follows.

const ctx = $input.first().json || {};

if (ctx.country !== 'nepal' || ctx.payment_provider !== 'monetix') {
  throw new Error('MONETIX_BRANCH_RECEIVED_NON_NEPAL_REQUEST');
}

const monetix_request = {
  // PLACEHOLDERS — DO NOT GUESS VALUES
  merchant_id: '',
  currency: ctx.currency || 'NPR',
  amount: ctx.amount,
  order_id: ctx.out_trade_no,
  phone: ctx.phone,
  callback_url: '',
  return_url: 'https://crm.lmtradermarkets.com/'
};

return [{
  json: {
    ...ctx,
    monetix_configured: false,
    monetix_request,
    monetix_configuration_status: 'WAITING_FOR_TECHNICAL_DETAILS'
  }
}];

// MONETIX RESPONSE NORMALIZER — SAFE PLACEHOLDER
// While the Monetix HTTP node is disabled/unconfigured, this returns a clean
// non-success response and NEVER falls through to the OkPay branch.
//
// Replace the response parsing section after the Monetix team provides
// the exact API response format.

let ctx = {};
try {
  ctx = $('🇳🇵 Build Monetix Request [CONFIG REQUIRED]').first().json || {};
} catch (e) {
  ctx = $input.first().json || {};
}

if (!ctx.monetix_configured) {
  return [{
    json: {
      ...ctx,
      success: false,
      refused: true,
      payment_provider: 'monetix',
      reason: 'MONETIX_CONFIGURATION_PENDING',
      user_message: 'Nepal payment link is temporarily unavailable while the payment gateway configuration is being completed.'
    }
  }];
}

// PLACEHOLDER FOR FUTURE LIVE RESPONSE PARSING
const resp = $input.first().json || {};

return [{
  json: {
    ...ctx,
    success: false,
    refused: false,
    payment_provider: 'monetix',
    raw_response: resp,
    reason: 'MONETIX_RESPONSE_PARSER_NOT_CONFIGURED',
    user_message: 'Nepal payment gateway response parser is not configured yet.'
  }
}];

const raw = $input.first().json;
const b = raw.body || raw;

// OkPay sends flat form fields
const status     = String(b.status || b.trade_status || '').toUpperCase();
const money      = String(b.money || b.amount || '');
const outTradeNo = String(b.out_trade_no || '');
const transId    = String(b.transaction_id || b.transactionId || b.trade_no || '');
const attach     = String(b.attach || ''); // echoed lead_id
const phone      = String(b.phone || '').replace(/[^0-9]/g, '');
const mchId      = String(b.mchId || b.mch_id || '');

console.log('📥 OkPay callback | status:', status, '| money:', money, '| out_trade_no:', outTradeNo, '| attach:', attach);

// OkPay success statuses
const isPaid = status === 'SUCCESS' || status === 'PAID' || status === '1' || status === 'COMPLETED';

if (!isPaid) {
  console.log('⚠️ Payment not successful, status:', status);
  return [{ json: { isPaid: false, status, outTradeNo, transId } }];
}

// Extract lead_id from attach or out_trade_no
let leadId = attach || outTradeNo;

return [{ json: {
  isPaid: true,
  status,
  money,
  outTradeNo,
  transId,
  leadId,
  phone,
  mchId,
  raw: b
}}];

const sms = $('📲 Send SMS Confirmation').first().json;
const ctx = $('⚙️ Parse Callback1').first().json;
console.log('✅ Payment processed | money:', ctx.money, '| txn:', ctx.transId, '| sms_http:', sms.statusCode);
return [{ json: {
  status: 'PROCESSED',
  money: ctx.money,
  transId: ctx.transId,
  outTradeNo: ctx.outTradeNo,
  sms_status: sms.statusCode
}}];

const ctx = $input.first().json;
console.log('⚠️ Payment not successful | status:', ctx.status, '| order:', ctx.outTradeNo);
return [{ json: { status: 'SKIPPED', reason: ctx.status } }];

const ctx = $input.first().json || {};

const link = ctx.short_url || ctx.checkout_url || '';

const country = String(ctx.country || '').toLowerCase();
const currency = String(ctx.currency || '').toUpperCase();
const amount = String(ctx.amount || '');

let amountLabel = `${currency} ${amount}`.trim();

if (country === 'india' && currency === 'INR') {
  amountLabel = `Rs${amount}`;
}

if (country === 'nepal' && currency === 'NPR') {
  amountLabel = `Rs${amount}`;
}

let brand = 'Landmark Markets';

const text = `${brand}: ${amountLabel} payment link: ${link}`;

return [{
  json: {
    ...ctx,
    sms_text: text
  }
}];

const smsResponse = $input.first().json;

let ctx = null;

try {
  ctx = $('🇮🇳 Parse OkPay Response').first().json;
} catch (e) {}

if (!ctx) {
  try {
    ctx = $('🇳🇵 Parse Monetix Response [CONFIG REQUIRED]').first().json;
  } catch (e) {}
}

ctx = ctx || {};

return [{
  json: {
    ...ctx,
    sms_response: smsResponse
  }
}];

const b = $input.first().json.body || $input.first().json;

function canonicalCountry(rawCountry, rawPhone='') {
  const c = String(rawCountry || '').trim().toLowerCase();

  if (['india','in'].includes(c)) return 'india';
  if (['nepal','np'].includes(c)) return 'nepal';

  const p = String(rawPhone || '').replace(/[^0-9+]/g,'');

  if (p.startsWith('+977') || p.startsWith('977')) return 'nepal';
  if (p.startsWith('+91') || p.startsWith('91')) return 'india';

  return '';
}

function normalizeDigits(rawPhone, country) {
  let d = String(rawPhone || '')
    .replace(/^=+/, '')
    .replace(/[^0-9]/g, '');

  if (!d) return '';

  if (country === 'india') {
    if (d.startsWith('91') && d.length === 12) return d;
    if (d.length === 10) return '91' + d;
  }

  if (country === 'nepal') {
    if (d.startsWith('977') && d.length >= 11 && d.length <= 15) return d;
    if (d.length >= 8 && d.length <= 10) return '977' + d;
  }

  return d;
}

const rawPhone = b.phone || b.lead_id || '';
const country = canonicalCountry(b.country, rawPhone);
