const country   = String(j.country || '').trim().toLowerCase();
const currency  = String(j.currency || '').trim().toUpperCase();
const amountNum = Number(String(j.amount || '0').replace(/^=/, '').trim());

const riskConfirmed =
  j.risk_disclosure_confirmed === true ||
  j.risk_disclosure_confirmed === 'true';

let whatsapp_phone = String(j.whatsapp_phone || '').replace(/[^0-9+]/g, '');
if (!whatsapp_phone) whatsapp_phone = phone ? ('+' + phone) : '';
if (whatsapp_phone && !whatsapp_phone.startsWith('+')) {
  whatsapp_phone = '+' + whatsapp_phone;
}

const payment_provider =
  country === 'india' ? 'okpay' :
  country === 'nepal' ? 'monetix' :
  '';

const errs = [];

if (!lead_id) errs.push('missing lead_id');
if (!phone) errs.push('missing phone');
if (!country) errs.push('unsupported/missing country');

if (!['india', 'nepal'].includes(country)) {
  errs.push('unsupported country: ' + country);
}

if (!payment_provider) {
  errs.push('payment provider not configured');
}

if (country === 'india' && currency !== 'INR') {
  errs.push('India payment currency must be INR');
}

if (country === 'nepal' && currency !== 'NPR') {
  errs.push('Nepal payment currency must be NPR');
}

// Preserve the existing India minimum exactly.
// Nepal minimum is still pending Monetix confirmation, therefore only require > 0 here.
// The Monetix request branch remains blocked until its API details are configured.
if (country === 'india' && (!Number.isFinite(amountNum) || amountNum < 2000)) {
  errs.push('India amount must be >= 2000');
}

if (country === 'nepal' && (!Number.isFinite(amountNum) || amountNum <= 0)) {
  errs.push('Nepal amount must be greater than 0');
}

if (Number.isFinite(amountNum) && amountNum > 500000) {
  errs.push('amount exceeds sanity ceiling 500000');
}

if (!riskConfirmed) {
  errs.push('risk_disclosure_confirmed must be true');
}

if (errs.length) {
  return [{
    json: {
      success: false,
      refused: true,
      country,
      payment_provider,
      reason: errs.join('; '),
      user_message: 'Payment link unavailable: ' + errs.join(', ')
    }
  }];
}

const out_trade_no = 'LM_' + lead_id + '_' + Date.now();
const idempotency_key = 'pay_' + out_trade_no;

return [{
  json: {
    ok: true,
    lead_id,
    full_name,
    phone,
    whatsapp_phone,
    country,
    currency,
    payment_provider,
    amount: String(Math.floor(amountNum)),
    out_trade_no,
    idempotency_key
  }
}];

