function clean(v) {
  return String(v || '').replace(/=/g, '').trim();
}

const ctx = $input.first().json;

// E.164 already normalized upstream; do not force +91 in a multi-country workflow.
let whatsapp_phone = String(ctx.whatsapp_phone || ctx.phone || '').replace(/[^0-9+]/g, '');
if (whatsapp_phone && !whatsapp_phone.startsWith('+')) whatsapp_phone = '+' + whatsapp_phone;

const params = {
  mchId:        '2764',
  currency:     clean(ctx.currency),
  out_trade_no: clean(ctx.out_trade_no),
  pay_type:     'UPI',
  money:        clean(ctx.amount),
  notify_url:   'https://landmarket-n8n.dhsoig.easypanel.host/webhook/okpay-callback',
  returnUrl:    'https://www.landmarkmarkets.in/sign-in',
  phone:        clean(ctx.phone),
  attach:       clean(ctx.lead_id),
};

const filtered = {};
for (const k of Object.keys(params)) {
  const v = params[k];
  if (v !== '' && v !== null && v !== undefined) filtered[k] = v;
}

const sortedKeys = Object.keys(filtered).sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
const baseString = sortedKeys.map(k => k + '=' + filtered[k]).join('&');
const toSign = baseString + '&key=' + 'a421742f0b404661b8ddb323c51cc99b';
const sign = md5(toSign);

const bodyParts = sortedKeys.map(k => encodeURIComponent(k) + '=' + encodeURIComponent(filtered[k]));
bodyParts.push('sign=' + sign);
const formBody = bodyParts.join('&');

return [{ json: { ...ctx, ...filtered, whatsapp_phone, sign, formBody } }];

const resp = $input.first().json || {};
const ctx = $('🇮🇳 Build OkPay Signed Request').first().json;

const code = resp.statusCode ?? resp.status ?? null;
const body = resp.body || resp;

const okpayCode = body.code;
const url = body.data && body.data.url;
const txnId = body.data && (body.data.transaction_Id || body.data.transactionId);

const success =
  code &&
  code >= 200 &&
  code < 300 &&
  okpayCode === 0 &&
  url;

if (success) {
  return [{
    json: {
      ...ctx,
      success: true,
      payment_provider: 'okpay',
      checkout_url: url,
      payment_transaction_id: txnId,
      okpay_transaction_id: txnId,
      http_status: code
    }
  }];
}

return [{
  json: {
    ...ctx,
    success: false,
    refused: false,
    payment_provider: 'okpay',
    reason:
      'OkPay error code=' + okpayCode +
      ' msg=' + (body.msg || '') +
      ' http=' + code,
